CREATE TABLE public.restaurant_delivery_settings (restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE, settings jsonb NOT NULL DEFAULT '{}', encrypted_password text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.restaurant_delivery_settings TO service_role;
ALTER TABLE public.restaurant_delivery_settings ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_configure_delivery(_rid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.is_super_admin() OR EXISTS(SELECT 1 FROM public.restaurant_members WHERE restaurant_id=_rid AND user_id=auth.uid() AND status='active' AND role='master')) $$;
REVOKE ALL ON FUNCTION public.can_configure_delivery(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_configure_delivery(uuid) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.online_shift_remaining(uuid,date,text)'::regprocedure) INTO def; def:=replace(def,'AND NOT(no_show AND NOT arrived)','AND status IN (''pending'',''confirmed'') AND NOT(no_show AND NOT arrived)'); EXECUTE def; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.restore_restaurant_data(uuid,jsonb)'::regprocedure) INTO def; def:=replace(def,'extra_phones,emails)','extra_phones,emails,marketing_consent,marketing_consent_at)'); def:=replace(def,'coalesce(p.extra_phones,''{}''), coalesce(p.emails,''{}'')','coalesce(p.extra_phones,''{}''), coalesce(p.emails,''{}''), coalesce(p.marketing_consent,false), p.marketing_consent_at'); def:=replace(def,'updated_at,deleted_at)','updated_at,deleted_at,status,rejection_reason,decided_at,channel,contact_email,privacy_consent_at,privacy_policy_url)'); def:=replace(def,'p.updated_at, p.deleted_at','p.updated_at, p.deleted_at, coalesce(p.status,''confirmed''), p.rejection_reason, p.decided_at, coalesce(p.channel,''internal''), p.contact_email, p.privacy_consent_at, p.privacy_policy_url'); EXECUTE def; END $$;